starterCode:
// Define Notificacion como una unión discriminada

function describir(n: Notificacion): string {
  switch (n.kind) {
    // Completa los dos casos
  }
  return "";
}

solution:
type Notificacion =
  | { kind: "exito"; mensaje: string }
  | { kind: "error"; codigo: number };

function describir(n: Notificacion): string {
  switch (n.kind) {
    case "exito": return n.mensaje;
    case "error": return `Error ${n.codigo}`;
  }
}
